    body: "문제가 생겼을 때 몇 명이 겪느냐다. 되돌리는 속도와 자원 비용이 그다음이다.\n\n| 기준 | 블루그린 | 카나리 |\n| --- | --- | --- |\n| 노출 범위 | 전환 즉시 전부 | 일부부터 |\n| 되돌리기 | 트래픽만 되돌린다 | 비율을 줄인다 |\n| 자원 | 두 벌이 필요 | 한 벌에 조금 더 |\n\n블루그린은 새 버전을 통째로 띄워 두고 트래픽만 옮긴다. 되돌리기가 가장 빠르지만 그 순간 모든 사용자가 새 버전을 만난다.\n\n카나리는 5%부터 늘린다. 문제가 있어도 그만큼만 겪지만, 두 버전이 동시에 도는 동안 DB 스키마가 양쪽과 맞아야 한다.\n\n무중단 배포에서는 구버전과 신버전이 같은 스키마를 함께 써야 한다. 구버전과 신버전이 함께 도는 무중단 배포에서는 컬럼을 한 번에 못 지운다. 읽기를 끊고, 쓰기를 끊고, 그다음에 지운다.",
