    body: "배치 작업은 처리량을, 응답형 서비스는 최악 지연 시간을 우선한다. 힙 크기, CPU 여유, 할당률과 실제 JDK 지원 범위도 함께 본다.\n\n| 기준 | Parallel GC | ZGC |\n| --- | --- | --- |\n| 우선 목표 | 높은 처리량 | 짧은 정지 |\n| 대가 | 긴 정지 가능 | CPU·메모리 여유 필요 |\n\nParallel GC는 수집 중 애플리케이션을 멈추고 여러 GC 스레드를 쓴다. 작업 완료량은 높지만 살아 있는 집합이 크면 정지가 길어진다.\n\nZGC는 표시와 재배치 대부분을 동시에 수행한다. 짧은 정지를 목표로 하지만 장벽 비용과 충분한 힙 여유가 필요하다.\n\nG1은 리전 단위로 수집해 처리량과 정지 목표를 절충한다. 선택 전 운영과 같은 부하에서 p99 지연, 처리량, GC CPU를 측정한다.",
