    body: "생성 뒤 상태가 변하지 않으면 여러 스레드가 잠금 없이 공유하기 쉽다. 해시 키도 안정된다. 대신 변경마다 새 객체가 필요하다.\n\n| 기준 | 불변 객체 | 가변 객체 |\n| --- | --- | --- |\n| 공유 | 동기화 부담이 작다 | 경쟁을 제어해야 한다 |\n| 변경 | 새 객체를 만든다 | 제자리에서 바꾼다 |\n\n필드를 private final로 두는 것만으로는 부족하다. 생성자에서 가변 인자를 복사하고 내부 배열과 컬렉션도 방어적 복사로 반환해야 한다.\n\nfinal 필드는 생성자 종료 뒤 초기화 안전성을 제공한다. 단, 생성 중 this가 외부로 노출되면 이 보장이 깨질 수 있다.\n\n작은 값 객체에는 잘 맞는다. 큰 그래프를 자주 갱신하면 할당과 복사 비용이 커져 빌더나 구조 공유 컬렉션이 필요할 수 있다.",
