    body: "원시 요청과 응답 전체에 적용할 일은 필터에 둔다. 선택된 컨트롤러 정보가 필요한 일은 인터셉터에 둔다. 비즈니스 규칙은 서비스에 둔다.\n\n| 기준 | 필터 | 인터셉터 |\n| --- | --- | --- |\n| 경계 | 서블릿 체인 | MVC 내부 |\n| 문맥 | 요청·응답 | 핸들러·모델 |\n| 용도 | 보안·인코딩 | 로깅·검사 |\n\n필터는 DispatcherServlet 전후를 감싸 정적 자원과 오류 디스패치에도 관여할 수 있다. 인터셉터는 preHandle이 참을 낼 때만 뒤가 이어진다. 거짓을 내면 거기서 끊기고 postHandle도 afterCompletion도 안 돈다.\n\n필터에서 난 예외는 보통 ControllerAdvice 범위 밖이다. 필터 체인에서 응답으로 바꾸거나 서블릿 오류 처리로 넘겨야 한다.\n\n실행 횟수와 순서도 설계 대상이다. 비동기·오류 디스패치에서는 필터가 다시 불릴 수 있어 OncePerRequestFilter 정책을 확인해야 한다.",
