    body: "격리 수준 이름부터 고르지 않는다. 동시에 실행돼도 절대 깨지면 안 되는 업무 규칙과, 충돌하면 다시 시도할 수 있는지를 먼저 본다.\n\n| 수준 | 보장하는 최소 범위 | 애플리케이션이 다룰 일 |\n| --- | --- | --- |\n| Read Committed | 완료되지 않은 변경은 읽지 않음 | 같은 트랜잭션의 두 조회가 다른 결과를 보여도 되는지 |\n| Repeatable Read | 한 트랜잭션의 반복 조회를 안정적으로 유지 | 구현별 팬텀·쓰기 충돌 처리 |\n| Serializable | 성공한 결과가 순차 실행 중 하나와 같음 | 직렬화 실패 시 트랜잭션 전체 재시도 |\n\n예를 들어 남은 좌석을 읽고 예약하는 두 트랜잭션은 각자만 보면 정상이다. 둘이 같이 성공하면 수용 인원을 넘길 수 있다. 이 규칙을 지키려면 원자적 갱신, 명시적 잠금, Serializable 중 하나로 경합을 다뤄야 한다.\n\n데이터베이스마다 같은 이름을 다르게 구현한다. PostgreSQL의 기본값은 Read Committed지만 InnoDB의 기본값은 Repeatable Read다. 기본값이 업무에 맞는다는 뜻은 아니다.\n\n수준을 올리면 항상 잠금이 늘어난다고도 단정할 수 없다. MVCC, 간격 잠금, 서로 다른 직렬화 구현이 있다. 실제 충돌률·대기 시간·재시도 횟수를 재고 선택한다.",
