    body: "애플리케이션의 서비스 특성과 지연 시간 허용 범위에 따라 결정한다. 처리량 중심인지, 응답 속도 중심인지가 핵심이다.\n\n| 기준 | Parallel GC | G1 GC | ZGC |\n| --- | --- | --- |\n| 목표 | 처리량 최대화 | 균형 잡힌 지연 | 초저지연 |\n| 특징 | STW 길다 | 리전 분할 관리 | 색상 포인터 사용 |\n\nParallel GC는 전체 처리량을 높이는 데 유리하다. 다만 GC가 돌면 그 JVM의 애플리케이션 스레드가 멈춘다. 그 시간이 길면 응답이 끊긴 것처럼 보인다.\n\nG1 GC는 힙을 리전으로 나누고 회수 가치가 큰 곳부터 수집한다. 설정한 목표 지연 시간을 맞추기 위해 수집 효율이 높은 영역부터 먼저 처리한다.\n\nZGC는 힙이 커져도 멈추는 시간이 잘 늘지 않도록 만들어졌다. 다만 몇 밀리초 아래라는 것은 목표이지 어떤 환경에서든 지켜지는 약속은 아니다. 컬러 포인터와 로드 배리어로 애플리케이션과 동시에 GC를 수행한다.",
